# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DAILY ROUTINES &amp; ADVERBS OF FREQUENCY (SIKLIK ZARFLARI)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ADVERBS OF FREQUENCY (%100 → %0)</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• 100%  Always (Daima / Her zaman)</text>\n  <text x="35" y="116" font-size="11" font-weight="bold" fill="#1d4ed8">• 85%   Usually / Generally (Genellikle)</text>\n  <text x="35" y="138" font-size="11" font-weight="bold" fill="#2563eb">• 70%   Often / Frequently (Sık sık)</text>\n  <text x="35" y="160" font-size="11" font-weight="bold" fill="#3b82f6">• 50%   Sometimes (Bazen / Ara sıra)</text>\n  <text x="35" y="182" font-size="11" font-weight="bold" fill="#64748b">• 15%   Rarely / Seldom / Hardly ever (Nadiren)</text>\n  <text x="35" y="204" font-size="11" font-weight="bold" fill="#b91c1c">• 0%    Never (Hiçbir zaman — Olumlu fiille!)</text>\n  <text x="35" y="226" font-size="10" fill="#0f172a">Konum: Ana fiilden ÖNCE, \'am/is/are\' yardımcı fiilinden SONRA!</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">HOW OFTEN ...? (NE SIKLIKLA?)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#14532d">• Soru: How often do you work out?</text>\n  <text x="383" y="114" font-size="10.5" fill="#166534">- I usually work out after school.</text>\n  <text x="383" y="132" font-size="10.5" fill="#166534">- She is always punctual for her classes.</text>\n  <text x="375" y="158" font-size="11" font-weight="bold" fill="#14532d">• Cümle Sonu Zaman İfadeleri:</text>\n  <text x="383" y="176" font-size="10.5" fill="#166534">- once a day (günde bir kez)</text>\n  <text x="383" y="194" font-size="10.5" fill="#166534">- twice a week (haftada iki kez)</text>\n  <text x="383" y="212" font-size="10.5" fill="#166534">- three times a month / every weekend</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FREE TIME ACTIVITIES &amp; VERBS OF PREFERENCE (+ V-ING)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">EXPRESSING LIKES &amp; DISLIKES (+ V-ing)</text>\n  <text x="35" y="96" font-size="10.5" font-weight="bold" fill="#15803d">• Olumlu: love / enjoy / like / be keen on /</text>\n  <text x="43" y="112" font-size="10.5" font-weight="bold" fill="#15803d">be fond of / be crazy about / be interested in + V-ing</text>\n  <text x="35" y="138" font-size="10.5" font-weight="bold" fill="#b45309">• Nötr: don\'t mind + V-ing (yapmakta sakınca görmemek)</text>\n  <text x="35" y="164" font-size="10.5" font-weight="bold" fill="#b91c1c">• Olumsuz: dislike / hate / can\'t stand + V-ing</text>\n  <text x="35" y="192" font-size="10.5" fill="#78350f">• Tercih: prefer + V-ing + TO + V-ing</text>\n  <text x="43" y="210" font-size="10" fill="#92400e">"I prefer reading sci-fi books to watching TV."</text>\n  <text x="43" y="226" font-size="10" fill="#92400e">"I would rather stay at home than go out tonight."</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">PLAY / GO / DO COLLOCATIONS</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#581c87">1. PLAY (Top oyunları, takım sporları, enstrüman):</text>\n  <text x="383" y="114" font-size="10.5" fill="#6b21a8">play basketball, chess, board games, the guitar</text>\n  <text x="375" y="142" font-size="11" font-weight="bold" fill="#581c87">2. GO (-ing ile biten açık hava / hareket etkinlikleri):</text>\n  <text x="383" y="160" font-size="10.5" fill="#6b21a8">go swimming, cycling, hiking, camping, jogging</text>\n  <text x="375" y="188" font-size="11" font-weight="bold" fill="#581c87">3. DO (Bireysel sporlar, egzersiz, dövüş sanatları):</text>\n  <text x="383" y="206" font-size="10.5" fill="#6b21a8">do yoga, archery, karate, gymnastics, puzzles</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PRESENT SIMPLE vs. PRESENT CONTINUOUS &amp; STATIVE VERBS</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PRESENT SIMPLE vs. CONTINUOUS</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Present Simple (V1 / V-s, don\'t / doesn\'t):</text>\n  <text x="43" y="110" font-size="10" fill="#1d4ed8">Kalıcı durumlar, rutinler, alışkanlıklar ve doğa yasaları.</text>\n  <text x="43" y="126" font-size="10" font-weight="bold" fill="#1e40af">"She usually wears casual clothes on weekdays."</text>\n  <text x="35" y="154" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Present Continuous (am/is/are + V-ing):</text>\n  <text x="43" y="170" font-size="10" fill="#1d4ed8">Konuşma anında (now, at the moment) veya bu</text>\n  <text x="43" y="186" font-size="10" fill="#1d4ed8">günlerde geçici olarak (these days) süren eylemler.</text>\n  <text x="43" y="202" font-size="10" font-weight="bold" fill="#b91c1c">"Look! She is wearing an elegant evening dress tonight."</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">STATIVE VERBS (DURUM FİİLLERİ — NO -ING!)</text>\n  <text x="375" y="94" font-size="10.5" fill="#881337">Eylem değil durum bildiren fiiller \'now\' olsa bile</text>\n  <text x="375" y="110" font-size="10.5" font-weight="bold" fill="#b91c1c">-ing eki ALMAZ, Present Simple ile kullanılır:</text>\n  <text x="375" y="136" font-size="10.5" font-weight="bold" fill="#881337">• Zihin: know, believe, understand, remember, mean</text>\n  <text x="375" y="158" font-size="10.5" font-weight="bold" fill="#881337">• Duygu/İstek: love, like, hate, prefer, want, need</text>\n  <text x="375" y="180" font-size="10.5" font-weight="bold" fill="#881337">• Sahiplik/Algı: have (sahip olmak), belong, seem, look</text>\n  <text x="375" y="206" font-size="10.5" font-weight="bold" fill="#15803d">Doğru: "I need your help right now." (NOT: I am needing)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
